import './index.less'
import { addItem } from '@shopify/theme-cart';
import { calcTop, isMobile, getSocialShareAPI, copyFunc } from '@utils/index.js'
import { getProductInfo } from "@utils/api.js";
import { gaPushDataLayer } from '../../common/utils';

class ArticleMain {
    constructor(id) {
        this.id = id;
        this.el = document.querySelector(this.id);
        this.DOM = {
            articleMain: this.el.querySelector('.new-article-main'),
            tableContent: this.el.querySelector('.table-content'),
            blogProductItems: this.el.querySelectorAll('.blog-product-item'),
            newArticleMainRight: this.el.querySelector('.new-article-main-right'),
        }
        this.data = {
            isShowH3: this.DOM.articleMain.dataset.showH3 === 'true',
            contentResult: [], // 存储标题
            productSwipersCount: Number(this.DOM.articleMain.dataset.productSwipersCount),
            originList: {}
        }
        this.initRelatedProducts()
        this.init()
    }
    // 初始化关联产品
    initRelatedProducts() {
        this.DOM.blogProductItems.forEach(item => {
            const id = item.dataset.productId || null
            if (id) {
                Object.assign(this.data.originList, {
                    [id]: {
                        id,
                        title: item.dataset.title || '',
                        description: item.dataset.description || '',
                        clas: item.dataset.clas || ''
                    }
                })
            }
        })
    }
    async init() {
        this.DOM.newArticleMainRight.style.top = `${calcTop()}px`
        // 等待页面加载完成
        this.handleContent()
        this.bindEvents();
        this.handleCalculator()
        this.gaRandomButton()
        if (this.data.productSwipersCount > 0) {
            this.handleProductSwipers();
        }
        await this.getReleatedProductList()
    }
    // 获取关联产品信息
    async handleProduct() {
        const keys = Object.keys(this.data.originList)
        const productList = []
        const fetchApi = []
        keys.forEach(async id => {
            fetchApi.push(getProductInfo({ spuId: id }))
        })
        const res = await Promise.allSettled(fetchApi)
        res.forEach(item => {
            const { status, value } = item
            if (status === 'fulfilled') {
                const { code, data } = value
                if (code === 200 && data !== null) {
                    const { product: { id, images, body_html, title, status, handle, variants } } = data
                    productList.push({
                        id,
                        images,
                        title,
                        description: body_html,
                        url: `/products/${handle}`,
                        variants,
                        clas: this.data.originList[id].clas
                    })
                }
            }
        })
        return productList
    }
    async getReleatedProductList() {
        const productList = await this.handleProduct()
        productList.forEach((item, index) => {
            let html = ''
            // 当只有一个变体时，需要判断是否有效
            const length = item.variants.length

            // flag为true则表示有效 false表示无效
            let flag = true
            if (length === 1) {
                const { inventory_quantity, inventory_policy, inventory_management } = item.variants[0]
                flag = inventory_quantity > 0 || inventory_policy === 'continue' || !inventory_management
            }
            const clas = flag ? 'bg-[var(--jds-color-primary)] hover:opacity-60' : 'bg-[var(--jds-color-primary)] cursor-not-allowed'
            const disabled = flag ? '' : 'disabled'
            const btn = item.variants.length > 1 ? `
                    <div
                        class="btn-learn-more flex-center rounded-100 font-600 text-[var(--jds-color-primary)] border border-[var(--jds-color-primary)] cursor-pointer mt-40 px-40 h-80 text-26 lg:a-mt-30 lg:a-px-32 lg:a-h-48 lg:a-text-18 hover:lg:bg-[var(--jds-color-primary)] hover:lg:text-#fff learn-more"
                        data-url="${item.url}"
                        data-id="${item.id}"
                        data-title="${item.title}"
                    >
                        ${$('.new-article-header').data('learn-more')}
                    </button>
                ` : `
                    <button
                        class="product-left-btn flex-center rounded-100 font-600 text-[var(--jds-color-primary)] border border-[var(--jds-color-primary)] cursor-pointer mt-40 px-40 h-80 text-26 mr-16 lg:a-mr-16 lg:a-mt-30 lg:a-px-32 lg:a-h-48 lg:a-text-18 hover:lg:bg-[var(--jds-color-primary)] hover:lg:text-#fff learn-more"
                        data-url="${item.url}"
                        data-id="${item.id}"
                        data-title="${item.title}"
                    >
                        ${$('.new-article-header').data('learn-more')}
                    </button>
                    <button
                        class="flex-center rounded-100 font-600 color-#fff cursor-pointer mt-40 px-40 h-80 text-26 lg:a-mt-30 lg:a-mt-0 lg:a-px-32 lg:a-h-48 lg:a-text-18  add-to-cart ${clas}"
                        data-id="${item.variants[0].id}"
                        data-sku="${item.variants[0].sku}"
                        data-title="${item.title}"
                        data-add-to-cart
                        ${disabled}
                    >
                        ${$('.new-article-header').data('add-to-cart')}
                    </button>
                `
            let slideHtml = ''
            item.images.forEach(img => {
                slideHtml += `
                        <swiper-slide>
                            <a href="${item.url}">
                            <img class="w-670 h-670 lg:a-w-380 lg:a-h-380" src="${img.src}" alt="${img.alt}">
                            </a>
                        </swiper-slide>
                    `
            })

            html += `
                <div class="lg:flex justify-between mb-60 lg:a-mb-16 article-product">
                    <a href="${item.url}" class="mobile-block">
                        <div class="font-600 color-#333333 text-34 leading-50 lg:a-text-24 lg:a-leading-32 line-clamp-3">${this.data.originList[item.id].title || item.title}</div>
                    </a>
                    <div class="swiper-content">
                        <swiper-container
                            class="w-full lg:a-w-380 swiper-${index}"
                            loop="true"
                            pagination="true"
                            autoplay-delay="5000"
                            autoplay-disable-on-interaction="false"
                            pagination-type="fraction"
                            style="
                                --swiper-navigation-color: #a5a4a4;
                                --swiper-pagination-color: var(--jds-color-primary);
                            "
                        >
                            ${slideHtml}
                            <div class="h-60 lg:a-h-34" slot="container-start"></div>
                            <div class="h-60 lg:a-h-34" slot="container-end"></div>
                        </swiper-container>
                        <div class="swiper-buttons">
                            <button data-index="${index}" class="swiper-button swiper-button-prev-new"><i class="iconfont jackery-icon-left"></i></button>
                            <button data-index="${index}" class="swiper-button swiper-button-next-new"><i class="iconfont jackery-icon-right"></i></button>
                        </div>
                    </div>
                    <div class="lg:a-w-380 mt-60 lg:a-mt-34 lg:a-mb-34 lg:flex flex-col justify-between swiper-bottom">
                        <div>
                            <a href="${item.url}" class="pc-block">
                                <div class="font-600 color-#333333 text-34 leading-50 lg:a-text-24 lg:a-leading-32 line-clamp-3">${this.data.originList[item.id].title || item.title}</div>
                            </a>
                            <div class="swiper-des mt-14 text-26 leading-38 lg:a-text-16 font-500 lg:a-leading-24 color-#666 lg:a-mt-13 line-clamp-7 product-${index}-description">
                                ${ this.data.originList[item.id].description ? this.handleReg(this.data.originList[item.id].description) :
                                    `
                                        <div class="rte">
                                            ${item.description}
                                        </div>
                                    `
                                }
                            </div>
                        </div>
                        <div class="flex items-center flex-wrap justify-center lg:justify-start">
                            ${btn}
                        </div>
                    </div>
                </div>
            `
            $(`.${item.clas}`).append(html)
        });
    }
    handleReg(text) {
        if (!text) return ''
        return text.replace(/(\r\n)|(\n)/g, '<br>')
    }
    gaRandomButton() {
        document.querySelectorAll('.article-button a').forEach((el) => {
            el.addEventListener('click', function (e) {
                const title = $('#article-new h1').text().trim() || '';
                const button_name = this.textContent.trim() || '';
                const link = this.href || '';
                let params = {
                    title,
                    button_name,
                    link,
                    module: "Blog Button"
                };

                window.dataLayer.push({ event_parameters: null });
                window.dataLayer.push({
                    event: 'ga4Event',
                    event_name: 'blog_detail_page_user_clicks',
                    event_parameters: {
                        current_page: window.location.href, // current page url
                        ...params,
                    },
                });

            });
        });
    }
    // 处理日本计算器逻辑，dom结构手动插入进去的，下面有判断有dom结构，再执行函数
    handleCalculator() {
        const calculatorDiv = document.getElementById('electric-calculator');
        if (calculatorDiv) {
            const tabs = document.querySelectorAll(".tab");
            const contents = document.querySelectorAll(".tab-content");

            tabs.forEach(tab => {
                tab.addEventListener("click", () => {
                    tabs.forEach(t => t.classList.remove("active"));
                    contents.forEach(c => c.classList.remove("active"));
                    tab.classList.add("active");
                    document.getElementById(tab.dataset.target).classList.add("active");
                });
            });

            document.getElementById("btn-current-to-power").addEventListener("click", function () {
                const current = parseFloat(document.getElementById("current-value").value);
                const unit = document.getElementById("current-unit").value;
                const voltage = parseFloat(document.getElementById("voltage-current").value);
                const result = document.getElementById("power-result");

                if (isNaN(current) || isNaN(voltage)) {
                    result.textContent = "有効な数値を入力してください";
                    return;
                }

                const amps = unit === "mA" ? current / 1000 : current;
                const watts = amps * voltage;
                const kW = watts / 1000;

                result.textContent = `${current} ${unit} × ${voltage}V = ${watts.toFixed(3)}W (${kW.toFixed(3)}kW)`;
            });

            document.getElementById("btn-power-to-current").addEventListener("click", function () {
                const power = parseFloat(document.getElementById("power-value").value);
                const unit = document.getElementById("power-unit").value;
                const voltage = parseFloat(document.getElementById("voltage-power").value);
                const result = document.getElementById("current-result");

                if (isNaN(power) || isNaN(voltage) || voltage === 0) {
                    result.textContent = "有効な数値を入力してください（電圧≠0）";
                    return;
                }

                const watts = unit === "kW" ? power * 1000 : power;
                const amps = watts / voltage;
                const mA = amps * 1000;

                result.textContent = `${power} ${unit} ÷ ${voltage}V = ${amps.toFixed(3)}A (${mA.toFixed(1)}mA)`;
            });
        }
    }

    /**
     * @description 处理文章内容，提取H2和H3标题，并生成层级结构
     */
    handleContent() {
        // 没有h2直接隐藏内容
        if ($('.article__body h2').length == 0) {
            $('.table-content-box').hide();
            return
        }

        const el = this.data.isShowH3 ? '.article__body h2, .article__body h3' : '.article__body h2';
        const headers = Array.from(document.querySelectorAll(el))
            .sort((a, b) => a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1);
        // 存储结果的结构化数据
        const result = [];
        let currentH2 = null;
        let counter = 0;
        headers.forEach((header) => {
            if (header.tagName === 'H2') {
                // 给 H2 编号
                header.dataset.priv = `article-priv-${counter++}`;
                currentH2 = { text: header.textContent, el: header, children: [] };
                result.push(currentH2);
            }else if (this.data.isShowH3 && header.tagName === 'H3' && currentH2) {
                // 只有有当前 H2 才统计 H3
                header.dataset.priv = `article-priv-${counter++}`;
                currentH2.children.push({
                    text: header.textContent,
                    el: header,
                });
            }
        });

        // 将结果插入到页面中
        const tableContent = this.DOM.tableContent || null;
        if (tableContent && result.length > 0) {
            this.data.contentResult = result; // 保存结果到data中
            let html = ``
            let counter = 0;
            result.forEach((item) => {
                html += `
                    <div class="artcile-h2 artcile-content-link" data-priv="${counter}">${item.text}</div>
                `;
                counter++;

                if (this.data.isShowH3 && item.children.length > 0) {
                    let h3Element = ``;
                    item.children.forEach((child) => {
                        h3Element += `
                            <div class="artcile-h3 artcile-content-link" data-priv="${counter}">${child.text}</div>
                        `;
                        counter++;
                    });
                    html += `<div class="artcile-h3-container">${h3Element}</div>`;
                }
            });
            tableContent.innerHTML = html;
        }

        if (this.data.isShowH3) {
            // 判断当前文本内容是否大于最大高度
            const tableContentHeight = tableContent.scrollHeight || 0;
            const tableContentMaxHeight = $('.table-content').css('max-height');
            const maxHeightValue = parseInt(tableContentMaxHeight, 10);
            if (tableContentHeight > maxHeightValue) {
                $('.article-view-more').css({ display: 'flex' });
            } else {
                $('.article-view-more').hide();
            }
        } else {
            // 如果不显示H3标题，则直接设置最大高度为内容高度
            $('.table-content').css({ maxHeight: `${tableContent.scrollHeight}px` });
            $('.article-view-more').hide();
        }
    }
    /**
     * @description 绑定事件
     */
    bindEvents() {
        const that = this
        $('.table-content').on('click', '.artcile-content-link', function () {
            const priv = $(this).data('priv')
            $('html, body').animate({
                scrollTop: $(`[data-priv='article-priv-${priv}']`).offset().top - calcTop()
            }, 300);
        })

        // 点击View More
        $('.article-view-more').click(function () {
            $('.table-content').css({ maxHeight: 'max-content' })
            $(this).remove();
        })

        // 加购
        $('body').on('click', '.add-to-cart', function () {
            $(this).addClass('btn--loading')
            const id = $(this).data('id')
            const sku = $(this).data('sku')
            that.addToCart(+id, {}, sku)
        })

        $('body').on('click', '.learn-more', function () {
            const gaParams = {
                title: $('.new-article-header').data('title'),
                module: "Blog Product Display",
                position: $(this).data('title'),
                button_name: $(this).text().trim(),
                link: $(this).data('url')
            }
            gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
            const flag = $('.new-article-header').data('new-blank')
            const url = $(this).data('url')
            if (flag) {
                window.open(url)
            } else {
                window.location.href = url
            }
        })

        $('.article-type').click(function () {
            const gaParams = {
                title: $('.new-article-header').data('title'),
                module: "Blog Type&Label ",
                position: $(this).text().trim(),
                link: $(this).attr('href')
            }
            gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
        })

        $('.related-article').click(function () {
            const gaParams = {
                title: $('.new-article-header').data('title'),
                module: "Blog Related Articles",
                position: $(this).text().trim(),
                link: $(this).attr('href')
            }
            gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
        })
        $('.article-image').click(function () {
            const gaParams = {
                title: $('.new-article-header').data('title'),
                module: "Blog Right_pic",
                position: 'sing_pic',
                link: $(this).attr('href')
            }
            gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
        })
        $('.shop-product').click(function () {
            const gaParams = {
                title: $('.new-article-header').data('title'),
                module: "Blog Bottom Product",
                position: $(this).text().trim(),
                link: $(this).attr('href')
            }
            gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
        })
        $('body').on('click', '.swiper-button-prev-new', function () {
            const index = $(this).data('index')
            const swiperEl = document.querySelector(`.swiper-${index}`);
            swiperEl.swiper.slidePrev();
        })

        $('body').on('click', '.swiper-button-next-new', function () {
            const index = $(this).data('index')
            const swiperEl = document.querySelector(`.swiper-${index}`);
            swiperEl.swiper.slideNext();
        })

        $('.blog-share').click(function () {
            const type = $(this).data('type')
            that.socialShareFunc(type)
        })
    }
    /**
     * @description 处理产品轮播
     */
    handleProductSwipers() {
        for (let i = 0; i < this.data.productSwipersCount; i++) {
            const swiperEl = document.querySelector(`.product-swiper-${i + 1}`);
            const insetClass = swiperEl?.dataset.swiperClass || ''
            const insetEl = document.querySelector(`.${insetClass}`) || null;
            if (swiperEl && insetEl) {
                const length = swiperEl.querySelectorAll('.swiper-slide').length;
                const navigationFlag = isMobile() ? length > 2 : length > 4;
                new Swiper(swiperEl, {
                    spaceBetween: 12,
                    slidesPerView: 2.2,
                    breakpoints: {
                        1024: {
                            spaceBetween: 16,
                            slidesPerView: 4
                        },
                    },
                    pagination: {
                        el: `.product-swiper--pagination-${i + 1}`,
                        clickable: true,
                    },
                    navigation: navigationFlag ?  {
                        nextEl: `.product-swiper--next-${i + 1}`,
                        prevEl: `.product-swiper--prev-${i + 1}`,
                    } : false,
                });
                insetEl.appendChild(swiperEl);

                if (!isMobile() && length > 4) {
                    $(`.product-swiper--next-${i + 1}`).css({ display: 'flex' });
                    $(`.product-swiper--prev-${i + 1}`).css({ display: 'flex' });
                }
            }
        }
    }
    // 添加到购物车
    async addToCart(id, properties = {}, sku) {
        if (!id) return
        let cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
        try {
            const res = await addItem(id, { quantity: 1, properties, })
            const gaParams = {
                title: $('.new-article-header').data('title'),
                module: "Blog Product Display",
                position: sku,
                button_name: $('.add-to-cart:eq(0)').text().trim(),
            }
            gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
            if (cart) {
                cart.renderContents(res)
            } else {
                window.location.href = '/cart'
            }
        } catch (e) {
            const err = await e.json()
            pushErrorMessage(err.description, 3000)
        } finally {
            if (cart && cart.classList.contains('is-empty'))
                cart.classList.remove('is-empty')
            document.querySelectorAll('[data-add-to-cart]').forEach(it => it.classList.remove('btn--loading'))
        }
    }
    socialShareFunc(type) {
        switch (type) {
            case 'Instagram':
                copyFunc(window.location.href);
                pushSuccessMessage($('.new-article-header').data('share-successful'), 5000);
                break;
            case 'email':
                window.location = "mailto:?subject=&cc=&body=";
                break;
            default:
                const shareUrl = getSocialShareAPI(type);
                this.openWindows(shareUrl);
                break;
        }

        const gaParams = {
            title: $('.new-article-header').data('title'),
            module: "Blog Share",
            position: type,
        }
        gaPushDataLayer('blog_detail_page_user_clicks', gaParams)
    }
    openWindows(url) {
        window.open(
            url,
            "单独窗口",
            "height=300,width=600,top=30,left=20,toolbar=no,menubar=no,scrollbars=no,resizable=no,location=no,status=no"
        );
    }
}

window.$(document).ready(function () {
    new ArticleMain('#article-new');
})
